srcDoc.css:
@import url("https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;0,700;1,500&family=Inter:wght@400;500;600;700&display=swap");
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.sl-app {
  --ink: #2F323B;
  --paper: #FEFEFE;
  --card: #FFFFFF;
  --line: #A7CDDE;
  --line-soft: rgba(167, 205, 222, 0.45);
  --text: #2F323B;
  --muted: #585A61;
  --gold: #2972A9;
  --gold-bright: #2E9BCB;
  --gold-soft: rgba(46, 155, 203, 0.12);
  --green: #2972A9;
  --green-soft: rgba(41, 114, 169, 0.08);
  --red: #585A61;
  --red-soft: rgba(167, 205, 222, 0.18);
  --danger: #8B3A3A;
  --danger-soft: rgba(139, 58, 58, 0.08);
  display: flex;
  height: 100vh;
  background: var(--paper);
  color: var(--text);
  font-family: "Inter", sans-serif;
}

.sidebar {
  width: 250px;
  background: var(--ink);
  color: #FEFEFE;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
}

.brand-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 22px 20px;
  border-bottom: 1px solid rgba(254, 254, 254, 0.08);
}

.brand-logo {
  width: 40px;
  height: 40px;
  display: block;
  object-fit: contain;
  border-radius: 11px;
  flex-shrink: 0;
}

.brand-text {
  display: flex;
  flex-direction: column;
}

.brand-name {
  font-family: "Playfair Display", serif;
  font-size: 15px;
  font-weight: 700;
}

.brand-tag {
  font-size: 9px;
  color: var(--gold-bright);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  margin-top: 2px;
}

.nav-menu {
  list-style: none;
  padding: 12px;
  flex: 1;
  overflow-y: auto;
}

.nav-group {
  margin-bottom: 6px;
}

.nav-section-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px 6px;
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(254, 254, 254, 0.35);
  cursor: pointer;
  user-select: none;
  transition: color 0.2s;
}

.nav-section-head:hover {
  color: rgba(254, 254, 254, 0.65);
}

.nav-section-head::after {
  content: "";
  width: 7px;
  height: 7px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(45deg);
  transition: transform 0.2s;
}

.nav-group.collapsed .nav-section-head::after {
  transform: rotate(-45deg);
}

.nav-group-items {
  list-style: none;
}

.nav-group.collapsed .nav-group-items {
  display: none;
}

.nav-item {
  position: relative;
  padding: 10px 14px;
  margin-bottom: 3px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
  color: rgba(254, 254, 254, 0.6);
  transition: all 0.2s;
}

.nav-item:hover {
  background: rgba(46, 155, 203, 0.1);
  color: #FEFEFE;
}

.nav-item.active {
  background: linear-gradient(90deg, rgba(46, 155, 203, 0.2), rgba(41, 114, 169, 0.04));
  color: var(--gold-bright);
}

.nav-item.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 22%;
  height: 56%;
  width: 3px;
  border-radius: 3px;
  background: var(--gold-bright);
}

.sidebar-footer {
  padding: 14px;
  border-top: 1px solid rgba(254, 254, 254, 0.08);
}

.logout-btn {
  width: 100%;
  padding: 10px;
  background: transparent;
  border: 1px solid rgba(167, 205, 222, 0.22);
  border-radius: 8px;
  color: rgba(254, 254, 254, 0.6);
  font-size: 12px;
  font-weight: 500;
  font-family: "Inter", sans-serif;
  cursor: pointer;
  transition: all 0.2s;
}

.logout-btn:hover {
  border-color: var(--gold-bright);
  color: var(--gold-bright);
}

.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 18px 28px;
  border-bottom: 1px solid var(--line);
  background: var(--card);
}

.topbar-kicker {
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--gold);
}

.topbar h2 {
  font-family: "Playfair Display", serif;
  font-size: 22px;
  font-weight: 700;
  margin-top: 2px;
}

.user-chip {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 8px 14px;
}

.user-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--green);
  color: #FEFEFE;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
}

.user-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.user-info #userEmail {
  font-size: 12px;
  font-weight: 600;
}

.role-badge {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gold-bright);
}

.content {
  flex: 1;
  padding: 26px 28px 42px;
  overflow-y: auto;
}

.query-intro {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 24px;
  margin-bottom: 22px;
}

.query-intro-copy {
  max-width: 760px;
}

.query-eyebrow {
  display: block;
  margin-bottom: 6px;
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--gold);
}

.query-intro h3 {
  font-family: "Playfair Display", serif;
  font-size: 24px;
  line-height: 1.2;
  margin-bottom: 7px;
}

.query-intro p {
  font-size: 13px;
  color: var(--muted);
  line-height: 1.7;
  max-width: 680px;
}

.query-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 11px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--card);
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  white-space: nowrap;
}

.query-status-pill::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--gold-bright);
}

.stepper-panel {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 18px 22px;
  margin-bottom: 20px;
}

.stepper {
  display: flex;
  align-items: center;
}

.step-item {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 130px;
}

.step-number {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  color: var(--muted);
  background: var(--paper);
  font-size: 11px;
  font-weight: 700;
  transition: all 0.2s;
}

.step-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.step-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
}

.step-caption {
  font-size: 9px;
  color: #7A7C82;
}

.step-item.active .step-number,
.step-item.done .step-number {
  border-color: var(--gold);
  background: var(--gold);
  color: #FFFFFF;
}

.step-item.active .step-label {
  color: var(--gold);
}

.step-item.done .step-label {
  color: var(--text);
}

.step-line {
  height: 1px;
  flex: 1;
  min-width: 30px;
  margin: 0 16px;
  background: var(--line);
}

.step-line.done {
  background: var(--gold);
}

.query-panel {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 22px;
  margin-bottom: 20px;
}

.panel-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 18px;
  margin-bottom: 18px;
}

.panel-head-copy h3 {
  font-family: "Playfair Display", serif;
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 4px;
}

.panel-head-copy p {
  font-size: 11px;
  color: var(--muted);
  line-height: 1.6;
}

.rule-group {
  border: 1px solid var(--line);
  border-radius: 13px;
  overflow: hidden;
  margin-bottom: 14px;
  background: #FFFFFF;
}

.rule-group-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  background: rgba(167, 205, 222, 0.09);
  border-bottom: 1px solid var(--line-soft);
}

.rule-group-title {
  display: flex;
  align-items: center;
  gap: 10px;
}

.group-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 28px;
  height: 28px;
  padding: 0 9px;
  border-radius: 8px;
  background: var(--ink);
  color: #FFFFFF;
  font-size: 10px;
  font-weight: 700;
}

.rule-group-title strong {
  font-family: "Playfair Display", serif;
  font-size: 15px;
}

.rule-group-title span:last-child {
  font-size: 10px;
  color: var(--muted);
}

.rule-group-body {
  padding: 8px 16px 14px;
}

.rule-row {
  display: grid;
  grid-template-columns: 150px minmax(0, 1fr);
  gap: 16px;
  padding: 14px 0;
  border-bottom: 1px solid var(--line-soft);
}

.rule-row:last-child {
  border-bottom: none;
}

.rule-meta {
  padding-top: 2px;
}

.rule-label {
  display: block;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 5px;
}

.rule-label.exclude {
  color: var(--ink);
}

.rule-help {
  display: block;
  font-size: 10px;
  line-height: 1.5;
  color: var(--muted);
}

.term-area {
  min-width: 0;
}

.term-entry {
  display: flex;
  gap: 8px;
}

.term-input {
  flex: 1;
  min-width: 0;
  height: 40px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--paper);
  font-family: "Inter", sans-serif;
  font-size: 12px;
  color: var(--text);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.term-input:focus {
  border-color: var(--gold);
  box-shadow: 0 0 0 3px var(--green-soft);
}

.btn-add-term {
  height: 40px;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: #FFFFFF;
  color: var(--gold);
  font-family: "Inter", sans-serif;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.btn-add-term:hover {
  border-color: var(--gold);
  background: var(--gold-soft);
}

.term-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 10px;
}

.term-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  max-width: 100%;
  padding: 6px 8px 6px 10px;
  border-radius: 999px;
  border: 1px solid rgba(41, 114, 169, 0.2);
  background: var(--green-soft);
  color: var(--gold);
  font-size: 10px;
  font-weight: 600;
}

.term-chip.exclude {
  color: var(--ink);
  background: rgba(167, 205, 222, 0.16);
  border-color: rgba(167, 205, 222, 0.7);
}

.term-chip-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.term-chip-remove {
  width: 18px;
  height: 18px;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: currentColor;
  cursor: pointer;
  font-size: 14px;
  line-height: 18px;
}

.term-chip-remove:hover {
  background: rgba(47, 50, 59, 0.08);
}

.group-connector {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 2px 0 14px;
}

.group-connector::before,
.group-connector::after {
  content: "";
  height: 1px;
  flex: 1;
  background: var(--line-soft);
}

.group-connector span {
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--ink);
  color: #FFFFFF;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
}

.query-section-title {
  font-family: "Playfair Display", serif;
  font-size: 17px;
  margin-bottom: 4px;
}

.query-section-help {
  font-size: 11px;
  color: var(--muted);
  line-height: 1.6;
  margin-bottom: 14px;
}

.source-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 20px;
}

.source-card {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 14px;
  cursor: pointer;
  background: #FFFFFF;
  transition: all 0.2s;
}

.source-card:hover {
  border-color: var(--gold);
  background: rgba(167, 205, 222, 0.06);
}

.source-card.selected {
  border-color: var(--gold);
  background: var(--green-soft);
}

.source-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  background: var(--gold-soft);
  color: var(--gold);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 13px;
  flex-shrink: 0;
}

.source-copy {
  flex: 1;
}

.source-copy strong {
  display: block;
  font-size: 12px;
  margin-bottom: 4px;
}

.source-copy span {
  display: block;
  font-size: 10px;
  line-height: 1.5;
  color: var(--muted);
}

.switch {
  position: relative;
  width: 38px;
  height: 22px;
  flex-shrink: 0;
}

.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.switch-slider {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  background: #D9E6EC;
  cursor: pointer;
  transition: 0.2s;
}

.switch-slider::before {
  content: "";
  position: absolute;
  width: 16px;
  height: 16px;
  left: 3px;
  top: 3px;
  border-radius: 50%;
  background: #FFFFFF;
  box-shadow: 0 1px 3px rgba(47, 50, 59, 0.2);
  transition: 0.2s;
}

.switch input:checked + .switch-slider {
  background: var(--gold);
}

.switch input:checked + .switch-slider::before {
  transform: translateX(16px);
}

.targets-wrap {
  margin-top: 18px;
}

.targets-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.target-choice {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #FFFFFF;
  cursor: pointer;
  transition: all 0.2s;
}

.target-choice:hover {
  border-color: var(--gold);
}

.target-choice.selected {
  background: var(--green-soft);
  border-color: var(--gold);
}

.target-choice.disabled {
  opacity: 0.48;
  cursor: not-allowed;
}

.target-choice input {
  width: 16px;
  height: 16px;
  accent-color: var(--gold);
  flex-shrink: 0;
}

.target-copy {
  min-width: 0;
  flex: 1;
}

.target-copy strong {
  display: block;
  font-size: 11px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.target-copy span {
  display: block;
  margin-top: 2px;
  font-size: 9px;
  text-transform: capitalize;
  color: var(--muted);
}

.targets-empty {
  padding: 24px 16px;
  border: 1px dashed var(--line);
  border-radius: 10px;
  font-size: 11px;
  line-height: 1.6;
  color: var(--muted);
  text-align: center;
}

.btn-link-danger {
  border: none;
  background: transparent;
  color: var(--danger);
  font-family: "Inter", sans-serif;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
}

.btn-link-danger:hover {
  text-decoration: underline;
}

.add-group-row {
  display: flex;
  justify-content: center;
  margin: 4px 0 22px;
}

.btn-add-group {
  height: 38px;
  padding: 0 16px;
  border: 1px dashed var(--gold);
  border-radius: 9px;
  background: var(--gold-soft);
  color: var(--gold);
  font-family: "Inter", sans-serif;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.btn-add-group:hover {
  background: rgba(46, 155, 203, 0.18);
}

.btn-add-group:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.query-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding-top: 4px;
}

.query-actions-right {
  display: flex;
  gap: 10px;
  margin-left: auto;
}

.btn-primary,
.btn-secondary {
  min-height: 42px;
  padding: 0 18px;
  border-radius: 10px;
  font-family: "Inter", sans-serif;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-primary {
  border: 1px solid var(--gold);
  background: var(--gold);
  color: #FFFFFF;
}

.btn-primary:hover {
  background: var(--ink);
  border-color: var(--ink);
  transform: translateY(-1px);
}

.btn-secondary {
  border: 1px solid var(--line);
  background: #FFFFFF;
  color: var(--text);
}

.btn-secondary:hover {
  border-color: var(--gold);
  color: var(--gold);
}

.query-message {
  display: none;
  margin-bottom: 16px;
  padding: 11px 13px;
  border-radius: 9px;
  font-size: 11px;
  line-height: 1.5;
}

.query-message.show {
  display: block;
}

.query-message.error {
  border: 1px solid rgba(139, 58, 58, 0.25);
  background: var(--danger-soft);
  color: var(--danger);
}

.query-message.info {
  border: 1px solid rgba(41, 114, 169, 0.22);
  background: var(--green-soft);
  color: var(--gold);
}

.preview-formula {
  padding: 18px;
  border-radius: 12px;
  background: var(--ink);
  color: #FFFFFF;
  margin-bottom: 18px;
}

.preview-formula-label {
  display: block;
  margin-bottom: 9px;
  color: var(--gold-bright);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.14em;
}

.preview-formula code {
  font-family: Consolas, "Courier New", monospace;
  font-size: 13px;
  line-height: 1.7;
  white-space: pre-wrap;
  word-break: break-word;
}

.preview-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 20px;
}

.preview-stat {
  border: 1px solid var(--line);
  border-radius: 11px;
  padding: 14px;
}

.preview-stat-label {
  display: block;
  margin-bottom: 5px;
  font-size: 9px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 700;
}

.preview-stat-value {
  display: block;
  font-family: "Playfair Display", serif;
  font-size: 20px;
  font-weight: 700;
  color: var(--gold);
}

.preview-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.preview-source {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid var(--line-soft);
  padding: 9px 0;
  font-size: 11px;
}

.preview-source:last-child {
  border-bottom: none;
}

.preview-source strong {
  font-size: 11px;
}

.preview-source span {
  color: var(--muted);
}

.save-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(220px, 0.6fr);
  gap: 16px;
  margin-bottom: 18px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.sl-input {
  width: 100%;
  height: 42px;
  padding: 0 12px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 10px;
  font-size: 13px;
  font-family: "Inter", sans-serif;
  color: var(--text);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.sl-input:focus {
  border-color: var(--green);
  box-shadow: 0 0 0 3px var(--green-soft);
}

.save-summary {
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
  margin-bottom: 20px;
}

.save-summary-row {
  display: grid;
  grid-template-columns: 180px minmax(0, 1fr);
  border-bottom: 1px solid var(--line-soft);
}

.save-summary-row:last-child {
  border-bottom: none;
}

.save-summary-label,
.save-summary-value {
  padding: 11px 13px;
  font-size: 11px;
}

.save-summary-label {
  background: rgba(167, 205, 222, 0.08);
  font-weight: 700;
  color: var(--muted);
}

.save-summary-value {
  word-break: break-word;
}

.badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.badge-active {
  background: rgba(41, 114, 169, 0.1);
  color: var(--green);
  border: 1px solid rgba(41, 114, 169, 0.16);
}

.badge-inactive {
  background: rgba(167, 205, 222, 0.25);
  color: var(--ink);
  border: 1px solid rgba(167, 205, 222, 0.75);
}

@media (max-width: 1050px) {
  .targets-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .preview-grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 820px) {
  .sidebar {
    width: 210px;
  }
  .content {
    padding: 20px;
  }
  .rule-row {
    grid-template-columns: 1fr;
    gap: 8px;
  }
  .source-options,
  .save-grid {
    grid-template-columns: 1fr;
  }
  .targets-grid {
    grid-template-columns: 1fr;
  }
  .step-caption {
    display: none;
  }
  .step-item {
    min-width: auto;
  }
}

