appsmith.onReady(function () {
  var navMenu = document.getElementById('navMenu');
  var role = 'viewer';
  var model = appsmith.model || {};
  var maxGroups = parseInt(model.query_max_groups || 3, 10);
  if (isNaN(maxGroups) || maxGroups < 1) {
    maxGroups = 3;
  }
  var queryState = {
    step: 1,
    groups: [{
      groupNo: 1,
      include: [],
      and: [],
      andNot: []
    }],
    selectedTargets: {},
    useWeb: false,
    name: '',
    status: 'active'
  };
  function decodeB64(value) {
    if (!value) {
      return [];
    }
    try {
      return JSON.parse(decodeURIComponent(escape(atob(value))));
    } catch (error) {
      return [];
    }
  }
  function esc(value) {
    var element = document.createElement('div');
    element.textContent = value == null ? '' : String(value);
    return element.innerHTML;
  }
  function normalizeText(value) {
    return String(value || '').replace(/\s+/g, ' ').trim();
  }
  function quoteTerm(value) {
    return '"' + String(value || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
  }
  function getTargets() {
    return decodeB64((appsmith.model || {}).targetsJson || '');
  }
  function getSelectedTargets() {
    return getTargets().filter(function (target) {
      return !!queryState.selectedTargets[target.id];
    });
  }
  function renumberGroups() {
    queryState.groups.forEach(function (group, index) {
      group.groupNo = index + 1;
    });
  }
  function totalTerms() {
    var total = 0;
    queryState.groups.forEach(function (group) {
      total += group.include.length;
      total += group.and.length;
      total += group.andNot.length;
    });
    return total;
  }
  function buildGroupFormula(group) {
    var parts = [];
    if (group.include.length > 0) {
      var includeExpression = group.include.map(quoteTerm).join(' OR ');
      if (group.include.length > 1) {
        includeExpression = '(' + includeExpression + ')';
      }
      parts.push(includeExpression);
    }
    group.and.forEach(function (term) {
      parts.push('AND ' + quoteTerm(term));
    });
    group.andNot.forEach(function (term) {
      parts.push('AND NOT ' + quoteTerm(term));
    });
    return parts.join(' ');
  }
  function buildFormula() {
    var formulas = [];
    queryState.groups.forEach(function (group) {
      var formula = buildGroupFormula(group);
      if (formula) {
        formulas.push(formula);
      }
    });
    if (formulas.length === 0) {
      return '';
    }
    if (formulas.length === 1) {
      return formulas[0];
    }
    return formulas.map(function (formula) {
      return '(' + formula + ')';
    }).join(' OR ');
  }
  function showMessage(message, type) {
    var box = document.getElementById('queryMessage');
    if (!box) {
      return;
    }
    box.className = 'query-message show ' + (type || 'info');
    box.textContent = message;
  }
  function clearMessage() {
    var box = document.getElementById('queryMessage');
    if (!box) {
      return;
    }
    box.className = 'query-message';
    box.textContent = '';
  }
  function setSaveButtonState(disabled, label) {
    var button = document.querySelector('[data-action="save-query"]');
    if (!button) {
      return;
    }
    button.disabled = !!disabled;
    if (label) {
      button.textContent = label;
    }
  }
  function validateBuild() {
    if (queryState.groups.length === 0) {
      return 'Debes crear al menos un grupo.';
    }
    for (var i = 0; i < queryState.groups.length; i++) {
      if (queryState.groups[i].include.length === 0) {
        return 'El Grupo ' + (i + 1) + ' necesita al menos un término en INCLUIR.';
      }
    }
    return '';
  }
  function addTerm(groupIndex, bucket, rawValue) {
    var value = normalizeText(rawValue);
    if (!value) {
      return;
    }
    var group = queryState.groups[groupIndex];
    if (!group || !group[bucket]) {
      return;
    }
    var exists = group[bucket].some(function (item) {
      return item.toLowerCase() === value.toLowerCase();
    });
    if (!exists) {
      group[bucket].push(value);
    }
    renderCurrentStep();
  }
  function removeTerm(groupIndex, bucket, termIndex) {
    var group = queryState.groups[groupIndex];
    if (!group || !group[bucket]) {
      return;
    }
    group[bucket].splice(termIndex, 1);
    renderCurrentStep();
  }
  function buildStepper() {
    var steps = [{
      number: 1,
      label: 'Construir',
      caption: 'Reglas y fuentes'
    }, {
      number: 2,
      label: 'Previsualizar',
      caption: 'Validar consulta'
    }, {
      number: 3,
      label: 'Guardar',
      caption: 'Nombre y estado'
    }];
    var html = '';
    steps.forEach(function (step, index) {
      var stateClass = '';
      if (queryState.step === step.number) {
        stateClass = ' active';
      } else if (queryState.step > step.number) {
        stateClass = ' done';
      }
      html += '<div class="step-item' + stateClass + '">' + '<div class="step-number">' + esc(step.number) + '</div>' + '<div class="step-copy">' + '<span class="step-label">' + esc(step.label) + '</span>' + '<span class="step-caption">' + esc(step.caption) + '</span>' + '</div>' + '</div>';
      if (index < steps.length - 1) {
        html += '<div class="step-line' + (queryState.step > step.number ? ' done' : '') + '"></div>';
      }
    });
    return html;
  }
  function renderChips(groupIndex, bucket, values, isExclude) {
    if (!values || values.length === 0) {
      return '';
    }
    var html = '<div class="term-chips">';
    values.forEach(function (term, index) {
      html += '<span class="term-chip' + (isExclude ? ' exclude' : '') + '">' + '<span class="term-chip-text">' + esc(term) + '</span>' + '<button' + ' type="button"' + ' class="term-chip-remove"' + ' data-action="remove-term"' + ' data-group="' + esc(groupIndex) + '"' + ' data-bucket="' + esc(bucket) + '"' + ' data-index="' + esc(index) + '"' + ' aria-label="Eliminar término"' + '>×</button>' + '</span>';
    });
    html += '</div>';
    return html;
  }
  function renderRuleRow(groupIndex, bucket, label, help, placeholder, isExclude) {
    var group = queryState.groups[groupIndex];
    return '<div class="rule-row">' + '<div class="rule-meta">' + '<span class="rule-label' + (isExclude ? ' exclude' : '') + '">' + esc(label) + '</span>' + '<span class="rule-help">' + esc(help) + '</span>' + '</div>' + '<div class="term-area">' + '<div class="term-entry">' + '<input' + ' class="term-input"' + ' type="text"' + ' autocomplete="off"' + ' data-term-input="1"' + ' data-group="' + esc(groupIndex) + '"' + ' data-bucket="' + esc(bucket) + '"' + ' placeholder="' + esc(placeholder) + '"' + '>' + '<button' + ' type="button"' + ' class="btn-add-term"' + ' data-action="add-term"' + ' data-group="' + esc(groupIndex) + '"' + ' data-bucket="' + esc(bucket) + '"' + '>' + 'Agregar' + '</button>' + '</div>' + renderChips(groupIndex, bucket, group[bucket], isExclude) + '</div>' + '</div>';
  }
  function renderGroup(group, index) {
    var removeButton = '';
    if (queryState.groups.length > 1) {
      removeButton = '<button' + ' type="button"' + ' class="btn-link-danger"' + ' data-action="remove-group"' + ' data-group="' + esc(index) + '"' + '>' + 'Eliminar grupo' + '</button>';
    }
    var html = '<div class="rule-group">' + '<div class="rule-group-head">' + '<div class="rule-group-title">' + '<span class="group-badge">' + esc(group.groupNo) + '</span>' + '<div>' + '<strong>' + 'Grupo ' + esc(group.groupNo) + '</strong>' + '<span>' + 'Reglas de coincidencia' + '</span>' + '</div>' + '</div>' + removeButton + '</div>' + '<div class="rule-group-body">' + renderRuleRow(index, 'include', 'Incluir', 'Uno o varios términos. Entre ellos se aplica OR.', 'Añade una palabra o frase', false) + renderRuleRow(index, 'and', 'AND', 'El resultado también debe contener estos términos.', 'Añade una condición obligatoria', false) + renderRuleRow(index, 'andNot', 'AND NOT', 'Excluir resultados que contengan estos términos.', 'Añade un término a excluir', true) + '</div>' + '</div>';
    if (index < queryState.groups.length - 1) {
      html += '<div class="group-connector">' + '<span>OR</span>' + '</div>';
    }
    return html;
  }
  function renderTargetChoices() {
    var rows = getTargets();
    if (rows.length === 0) {
      return '<div class="targets-empty">' + 'No hay objetivos sociales disponibles para esta cuenta.' + '</div>';
    }
    var html = '<div class="targets-grid">';
    rows.forEach(function (target) {
      var active = target.status === 'active';
      var selected = !!queryState.selectedTargets[target.id];
      var displayName = target.handle || target.external_profile_id || 'Objetivo';
      html += '<label class="target-choice' + (selected ? ' selected' : '') + (!active ? ' disabled' : '') + '">' + '<input' + ' type="checkbox"' + ' data-target-id="' + esc(target.id) + '"' + (selected ? ' checked' : '') + (!active ? ' disabled' : '') + '>' + '<span class="target-copy">' + '<strong>' + esc(displayName) + '</strong>' + '<span>' + esc(target.platform || '') + (active ? '' : ' · Inactivo') + '</span>' + '</span>' + '</label>';
    });
    html += '</div>';
    return html;
  }
  function renderBuildStep() {
    var groupsHtml = '';
    queryState.groups.forEach(function (group, index) {
      groupsHtml += renderGroup(group, index);
    });
    var addDisabled = queryState.groups.length >= maxGroups;
    return '<section class="query-panel">' + '<div class="panel-head">' + '<div class="panel-head-copy">' + '<h3>Construir consulta</h3>' + '<p>' + 'Define los términos, exclusiones y fuentes que formarán parte del monitoreo.' + '</p>' + '</div>' + '</div>' + '<div id="queryMessage" class="query-message"></div>' + groupsHtml + '<div class="add-group-row">' + '<button' + ' type="button"' + ' class="btn-add-group"' + ' data-action="add-group"' + (addDisabled ? ' disabled' : '') + '>' + (addDisabled ? 'Límite de grupos alcanzado' : '+ Agregar otro grupo') + '</button>' + '</div>' + '<h4 class="query-section-title">' + 'Fuentes de la consulta' + '</h4>' + '<p class="query-section-help">' + 'Combina reglas temáticas, objetivos sociales disponibles y búsqueda web.' + '</p>' + '<div class="source-options">' + '<div class="source-card selected">' + '<div class="source-icon">Aa</div>' + '<div class="source-copy">' + '<strong>Palabras y frases</strong>' + '<span>' + 'Las reglas configuradas forman la expresión temática de la consulta.' + '</span>' + '</div>' + '</div>' + '<label class="source-card' + (queryState.useWeb ? ' selected' : '') + '">' + '<div class="source-icon">W</div>' + '<div class="source-copy">' + '<strong>Búsqueda web</strong>' + '<span>' + 'Incluye resultados procedentes del motor web configurado en el sistema.' + '</span>' + '</div>' + '<span class="switch">' + '<input' + ' id="useWeb"' + ' type="checkbox"' + (queryState.useWeb ? ' checked' : '') + '>' + '<span class="switch-slider"></span>' + '</span>' + '</label>' + '</div>' + '<div class="targets-wrap">' + '<h4 class="query-section-title">' + 'Objetivos sociales' + '</h4>' + '<p class="query-section-help">' + 'Selecciona los perfiles disponibles que deberán formar parte de esta consulta.' + '</p>' + renderTargetChoices() + '</div>' + '<div class="query-actions">' + '<div></div>' + '<div class="query-actions-right">' + '<button' + ' type="button"' + ' class="btn-primary"' + ' data-action="go-preview"' + '>' + 'Previsualizar →' + '</button>' + '</div>' + '</div>' + '</section>';
  }
  function renderPreviewStep() {
    var formula = buildFormula() || 'Sin fórmula';
    var selectedTargets = getSelectedTargets();
    var sourceRows = '';
    sourceRows += '<div class="preview-source">' + '<strong>Palabras y frases</strong>' + '<span>' + esc(totalTerms()) + ' término(s)' + '</span>' + '</div>';
    sourceRows += '<div class="preview-source">' + '<strong>Objetivos sociales</strong>' + '<span>' + esc(selectedTargets.length) + ' seleccionado(s)' + '</span>' + '</div>';
    sourceRows += '<div class="preview-source">' + '<strong>Búsqueda web</strong>' + '<span>' + (queryState.useWeb ? 'Incluida' : 'No incluida') + '</span>' + '</div>';
    var targetDetail = '';
    if (selectedTargets.length > 0) {
      targetDetail = '<section class="query-panel">' + '<div class="panel-head">' + '<div class="panel-head-copy">' + '<h3>Objetivos incluidos</h3>' + '<p>' + 'Perfiles sociales seleccionados para esta consulta.' + '</p>' + '</div>' + '</div>' + '<div class="preview-list">';
      selectedTargets.forEach(function (target) {
        targetDetail += '<div class="preview-source">' + '<strong>' + esc(target.handle || target.external_profile_id || 'Objetivo') + '</strong>' + '<span>' + esc(target.platform || '') + '</span>' + '</div>';
      });
      targetDetail += '</div>' + '</section>';
    }
    return '<section class="query-panel">' + '<div class="panel-head">' + '<div class="panel-head-copy">' + '<h3>Previsualizar consulta</h3>' + '<p>' + 'Verifica la lógica y las fuentes antes de guardar.' + '</p>' + '</div>' + '</div>' + '<div id="queryMessage" class="query-message"></div>' + '<div class="preview-formula">' + '<span class="preview-formula-label">' + 'Fórmula resultante' + '</span>' + '<code>' + esc(formula) + '</code>' + '</div>' + '<div class="preview-grid">' + '<div class="preview-stat">' + '<span class="preview-stat-label">Grupos</span>' + '<span class="preview-stat-value">' + esc(queryState.groups.length) + '</span>' + '</div>' + '<div class="preview-stat">' + '<span class="preview-stat-label">Términos</span>' + '<span class="preview-stat-value">' + esc(totalTerms()) + '</span>' + '</div>' + '<div class="preview-stat">' + '<span class="preview-stat-label">Objetivos</span>' + '<span class="preview-stat-value">' + esc(selectedTargets.length) + '</span>' + '</div>' + '</div>' + '<div class="preview-list">' + sourceRows + '</div>' + '<div class="query-actions">' + '<button' + ' type="button"' + ' class="btn-secondary"' + ' data-action="back-build"' + '>' + '← Volver a construir' + '</button>' + '<div class="query-actions-right">' + '<button' + ' type="button"' + ' class="btn-primary"' + ' data-action="go-save"' + '>' + 'Continuar →' + '</button>' + '</div>' + '</div>' + '</section>' + targetDetail;
  }
  function renderSaveStep() {
    var formula = buildFormula();
    var selectedTargets = getSelectedTargets();
    return '<section class="query-panel">' + '<div class="panel-head">' + '<div class="panel-head-copy">' + '<h3>Guardar consulta</h3>' + '<p>' + 'Asigna un nombre y define el estado inicial de la consulta.' + '</p>' + '</div>' + '</div>' + '<div id="queryMessage" class="query-message"></div>' + '<div class="save-grid">' + '<div class="field">' + '<label' + ' class="field-label"' + ' for="queryName"' + '>' + 'Nombre de la consulta' + '</label>' + '<input' + ' id="queryName"' + ' class="sl-input"' + ' type="text"' + ' maxlength="200"' + ' placeholder="Nombre de la consulta"' + ' value="' + esc(queryState.name) + '"' + '>' + '</div>' + '<div class="field">' + '<label' + ' class="field-label"' + ' for="queryStatus"' + '>' + 'Estado' + '</label>' + '<select' + ' id="queryStatus"' + ' class="sl-input"' + '>' + '<option value="active"' + (queryState.status === 'active' ? ' selected' : '') + '>' + 'Activa' + '</option>' + '<option value="inactive"' + (queryState.status === 'inactive' ? ' selected' : '') + '>' + 'Inactiva' + '</option>' + '</select>' + '</div>' + '</div>' + '<div class="save-summary">' + '<div class="save-summary-row">' + '<div class="save-summary-label">Fórmula</div>' + '<div class="save-summary-value">' + esc(formula) + '</div>' + '</div>' + '<div class="save-summary-row">' + '<div class="save-summary-label">Grupos</div>' + '<div class="save-summary-value">' + esc(queryState.groups.length) + '</div>' + '</div>' + '<div class="save-summary-row">' + '<div class="save-summary-label">Objetivos sociales</div>' + '<div class="save-summary-value">' + esc(selectedTargets.length) + '</div>' + '</div>' + '<div class="save-summary-row">' + '<div class="save-summary-label">Búsqueda web</div>' + '<div class="save-summary-value">' + (queryState.useWeb ? 'Sí' : 'No') + '</div>' + '</div>' + '</div>' + '<div class="query-actions">' + '<button' + ' type="button"' + ' class="btn-secondary"' + ' data-action="back-preview"' + '>' + '← Volver' + '</button>' + '<div class="query-actions-right">' + '<button' + ' type="button"' + ' class="btn-primary"' + ' data-action="save-query"' + '>' + 'Guardar consulta' + '</button>' + '</div>' + '</div>' + '</section>';
  }
  function renderCurrentStep() {
    var stepper = document.getElementById('queryStepper');
    var stage = document.getElementById('queryStage');
    if (stepper) {
      stepper.innerHTML = buildStepper();
    }
    if (!stage) {
      return;
    }
    if (queryState.step === 1) {
      stage.innerHTML = renderBuildStep();
    } else if (queryState.step === 2) {
      stage.innerHTML = renderPreviewStep();
    } else {
      stage.innerHTML = renderSaveStep();
    }
  }
  function prepareQueryPayload() {
    var groupsPayload = queryState.groups.map(function (group) {
      return {
        group_no: group.groupNo,
        include: group.include.slice(),
        and: group.and.slice(),
        and_not: group.andNot.slice()
      };
    });
    var targetIds = Object.keys(queryState.selectedTargets).filter(function (id) {
      return !!queryState.selectedTargets[id];
    });
    return {
      query_name: queryState.name,
      query_status: queryState.status,
      query_formula: buildFormula(),
      query_use_web: queryState.useWeb,
      query_groups_json: JSON.stringify(groupsPayload),
      query_target_ids_json: JSON.stringify(targetIds)
    };
  }
  function initQueriesModule() {
    var area = document.getElementById('contentArea');
    if (!area) {
      return;
    }
    var title = document.getElementById('viewTitle');
    if (title) {
      title.textContent = 'Consultas';
    }
    area.innerHTML = '<section class="query-intro">' + '<div class="query-intro-copy">' + '<span class="query-eyebrow">' + 'Configuración de escucha' + '</span>' + '<h3>Crear una nueva consulta</h3>' + '<p>' + 'Combina términos, exclusiones, objetivos sociales y búsqueda web dentro de un mismo contexto de monitoreo.' + '</p>' + '</div>' + '<div class="query-status-pill">' + 'Constructor de consultas' + '</div>' + '</section>' + '<section class="stepper-panel">' + '<div id="queryStepper" class="stepper"></div>' + '</section>' + '<div id="queryStage"></div>';
    renderCurrentStep();
    area.addEventListener('click', function (event) {
      var button = event.target.closest('[data-action]');
      if (!button) {
        return;
      }
      var action = button.getAttribute('data-action');
      if (action === 'add-term') {
        var groupIndex = parseInt(button.getAttribute('data-group'), 10);
        var bucket = button.getAttribute('data-bucket');
        var input = area.querySelector('[data-term-input="1"]' + '[data-group="' + groupIndex + '"]' + '[data-bucket="' + bucket + '"]');
        if (input) {
          addTerm(groupIndex, bucket, input.value);
        }
        return;
      }
      if (action === 'remove-term') {
        removeTerm(parseInt(button.getAttribute('data-group'), 10), button.getAttribute('data-bucket'), parseInt(button.getAttribute('data-index'), 10));
        return;
      }
      if (action === 'add-group') {
        if (queryState.groups.length >= maxGroups) {
          return;
        }
        queryState.groups.push({
          groupNo: queryState.groups.length + 1,
          include: [],
          and: [],
          andNot: []
        });
        renderCurrentStep();
        return;
      }
      if (action === 'remove-group') {
        var index = parseInt(button.getAttribute('data-group'), 10);
        if (queryState.groups.length <= 1) {
          return;
        }
        queryState.groups.splice(index, 1);
        renumberGroups();
        renderCurrentStep();
        return;
      }
      if (action === 'go-preview') {
        clearMessage();
        var error = validateBuild();
        if (error) {
          showMessage(error, 'error');
          return;
        }
        queryState.step = 2;
        renderCurrentStep();
        return;
      }
      if (action === 'back-build') {
        queryState.step = 1;
        renderCurrentStep();
        return;
      }
      if (action === 'go-save') {
        queryState.step = 3;
        renderCurrentStep();
        return;
      }
      if (action === 'back-preview') {
        queryState.step = 2;
        renderCurrentStep();
        return;
      }
      if (action === 'save-query') {
        var nameInput = document.getElementById('queryName');
        var statusInput = document.getElementById('queryStatus');
        queryState.name = normalizeText(nameInput ? nameInput.value : queryState.name);
        queryState.status = statusInput ? statusInput.value : queryState.status;
        if (!queryState.name) {
          showMessage('Debes indicar un nombre para la consulta.', 'error');
          if (nameInput) {
            nameInput.focus();
          }
          return;
        }
        var payload = prepareQueryPayload();
        appsmith.updateModel(payload);
        showMessage('Guardando consulta...', 'info');
        setSaveButtonState(true, 'Guardando...');
        setTimeout(function () {
          appsmith.triggerEvent('onSaveQuery');
        }, 150);
        return;
      }
    });
    area.addEventListener('keydown', function (event) {
      var input = event.target.closest('[data-term-input="1"]');
      if (!input) {
        return;
      }
      if (event.key !== 'Enter' && event.key !== ',') {
        return;
      }
      event.preventDefault();
      addTerm(parseInt(input.getAttribute('data-group'), 10), input.getAttribute('data-bucket'), input.value);
    });
    area.addEventListener('change', function (event) {
      if (event.target.id === 'useWeb') {
        queryState.useWeb = !!event.target.checked;
        var sourceCard = event.target.closest('.source-card');
        if (sourceCard) {
          sourceCard.classList.toggle('selected', queryState.useWeb);
        }
        return;
      }
