  transform: translateX(16px);
}

.targets-wrap {
  margin-top: 18px;
}

.targets-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.target-choice {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #FFFFFF;
  cursor: pointer;
  transition: all 0.2s;
}

.target-choice:hover {
  border-color: var(--gold);
}

.target-choice.selected {
  background: var(--green-soft);
  border-color: var(--gold);
}

.target-choice.disabled {
  opacity: 0.48;
  cursor: not-allowed;
}

.target-choice input {
  width: 16px;
  height: 16px;
  accent-color: var(--gold);
  flex-shrink: 0;
}

.target-copy {
  min-width: 0;
  flex: 1;
}

.target-copy strong {
  display: block;
  font-size: 11px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.target-copy span {
  display: block;
  margin-top: 2px;
  font-size: 9px;
  text-transform: capitalize;
  color: var(--muted);
}

.targets-empty {
  padding: 24px 16px;
  border: 1px dashed var(--line);
  border-radius: 10px;
  font-size: 11px;
  line-height: 1.6;
  color: var(--muted);
  text-align: center;
}

.btn-link-danger {
  border: none;
  background: transparent;
  color: var(--danger);
  font-family: 'Inter', sans-serif;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
}

.btn-link-danger:hover {
  text-decoration: underline;
}

.add-group-row {
  display: flex;
  justify-content: center;
  margin: 4px 0 22px;
}

.btn-add-group {
  height: 38px;
  padding: 0 16px;
  border: 1px dashed var(--gold);
  border-radius: 9px;
  background: var(--gold-soft);
  color: var(--gold);
  font-family: 'Inter', sans-serif;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.btn-add-group:hover {
  background: rgba(46, 155, 203, 0.18);
}

.btn-add-group:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.query-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding-top: 4px;
}

.query-actions-right {
  display: flex;
  gap: 10px;
  margin-left: auto;
}

.btn-primary,
.btn-secondary {
  min-height: 42px;
  padding: 0 18px;
  border-radius: 10px;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-primary {
  border: 1px solid var(--gold);
  background: var(--gold);
  color: #FFFFFF;
}

.btn-primary:hover {
  background: var(--ink);
  border-color: var(--ink);
  transform: translateY(-1px);
}

.btn-secondary {
  border: 1px solid var(--line);
  background: #FFFFFF;
  color: var(--text);
}

.btn-secondary:hover {
  border-color: var(--gold);
  color: var(--gold);
}

.query-message {
  display: none;
  margin-bottom: 16px;
  padding: 11px 13px;
  border-radius: 9px;
  font-size: 11px;
  line-height: 1.5;
}

.query-message.show {
  display: block;
}

.query-message.error {
  border: 1px solid rgba(139, 58, 58, 0.25);
  background: var(--danger-soft);
  color: var(--danger);
}

.query-message.info {
  border: 1px solid rgba(41, 114, 169, 0.22);
  background: var(--green-soft);
  color: var(--gold);
}

.preview-formula {
  padding: 18px;
  border-radius: 12px;
  background: var(--ink);
  color: #FFFFFF;
  margin-bottom: 18px;
}

.preview-formula-label {
  display: block;
  margin-bottom: 9px;
  color: var(--gold-bright);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.14em;
}

.preview-formula code {
  font-family: Consolas, 'Courier New', monospace;
  font-size: 13px;
  line-height: 1.7;
  white-space: pre-wrap;
  word-break: break-word;
}

.preview-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 20px;
}

.preview-stat {
  border: 1px solid var(--line);
  border-radius: 11px;
  padding: 14px;
}

.preview-stat-label {
  display: block;
  margin-bottom: 5px;
  font-size: 9px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.10em;
  font-weight: 700;
}

.preview-stat-value {
  display: block;
  font-family: 'Playfair Display', serif;
  font-size: 20px;
  font-weight: 700;
  color: var(--gold);
}

.preview-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.preview-source {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  border-bottom: 1px solid var(--line-soft);
  padding: 9px 0;
  font-size: 11px;
}

.preview-source:last-child {
  border-bottom: none;
}

.preview-source strong {
  font-size: 11px;
}

.preview-source span {
  color: var(--muted);
}

.save-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(220px, 0.6fr);
  gap: 16px;
  margin-bottom: 18px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.sl-input {
  width: 100%;
  height: 42px;
  padding: 0 12px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 10px;
  font-size: 13px;
  font-family: 'Inter', sans-serif;
  color: var(--text);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.sl-input:focus {
  border-color: var(--green);
  box-shadow: 0 0 0 3px var(--green-soft);
}

.save-summary {
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
  margin-bottom: 20px;
}

.save-summary-row {
  display: grid;
  grid-template-columns: 180px minmax(0, 1fr);
  border-bottom: 1px solid var(--line-soft);
}

.save-summary-row:last-child {
  border-bottom: none;
}

.save-summary-label,
.save-summary-value {
  padding: 11px 13px;
  font-size: 11px;
}

.save-summary-label {
  background: rgba(167, 205, 222, 0.08);
  font-weight: 700;
  color: var(--muted);
}

.save-summary-value {
  word-break: break-word;
}

.badge {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.badge-active {
  background: rgba(41, 114, 169, 0.10);
  color: var(--green);
  border: 1px solid rgba(41, 114, 169, 0.16);
}

.badge-inactive {
  background: rgba(167, 205, 222, 0.25);
  color: var(--ink);
  border: 1px solid rgba(167, 205, 222, 0.75);
}

@media (max-width: 1050px) {
  .targets-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .preview-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 820px) {
  .sidebar {
    width: 210px;
  }

  .content {
    padding: 20px;
  }

  .rule-row {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .source-options,
  .save-grid {
    grid-template-columns: 1fr;
  }

  .targets-grid {
    grid-template-columns: 1fr;
  }

  .step-caption {
    display: none;
  }

  .step-item {
    min-width: auto;
  }
}

