  function renderCurrentStep() {
    var stepper =
      document.getElementById('queryStepper');

    var stage =
      document.getElementById('queryStage');

    if (stepper) {
      stepper.innerHTML =
        buildStepper();
    }

    if (!stage) {
      return;
    }

    if (queryState.step === 1) {
      stage.innerHTML =
        renderBuildStep();
    } else if (queryState.step === 2) {
      stage.innerHTML =
        renderPreviewStep();
    } else {
      stage.innerHTML =
        renderSaveStep();
    }
  }

  function prepareQueryPayload() {
    var groupsPayload =
      queryState.groups.map(function (group) {
        return {
          group_no: group.groupNo,
          include: group.include.slice(),
          and: group.and.slice(),
          and_not: group.andNot.slice()
        };
      });

    var targetIds =
      Object.keys(
        queryState.selectedTargets
      ).filter(function (id) {
        return !!queryState.selectedTargets[id];
      });

    return {
      query_name: queryState.name,
      query_status: queryState.status,
      query_formula: buildFormula(),
      query_use_web: queryState.useWeb,
      query_groups_json:
        JSON.stringify(groupsPayload),
      query_target_ids_json:
        JSON.stringify(targetIds)
    };
  }

  function initQueriesModule() {
    var area =
      document.getElementById('contentArea');

    if (!area) {
      return;
    }

    var title =
      document.getElementById('viewTitle');

    if (title) {
      title.textContent = 'Consultas';
    }

    area.innerHTML =
      '<section class="query-intro">' +

        '<div class="query-intro-copy">' +

          '<span class="query-eyebrow">' +
            'Configuración de escucha' +
          '</span>' +

          '<h3>Crear una nueva consulta</h3>' +

          '<p>' +
            'Combina términos, exclusiones, objetivos sociales y búsqueda web dentro de un mismo contexto de monitoreo.' +
          '</p>' +

        '</div>' +

        '<div class="query-status-pill">' +
          'Constructor de consultas' +
        '</div>' +

      '</section>' +

      '<section class="stepper-panel">' +
        '<div id="queryStepper" class="stepper"></div>' +
      '</section>' +

      '<div id="queryStage"></div>';

    renderCurrentStep();

    area.addEventListener(
      'click',
      function (event) {
        var button =
          event.target.closest('[data-action]');

        if (!button) {
          return;
        }

        var action =
          button.getAttribute('data-action');

        if (action === 'add-term') {
          var groupIndex =
            parseInt(
              button.getAttribute('data-group'),
              10
            );

          var bucket =
            button.getAttribute('data-bucket');

          var input =
            area.querySelector(
              '[data-term-input="1"]' +
              '[data-group="' +
                groupIndex +
              '"]' +
              '[data-bucket="' +
                bucket +
              '"]'
            );

          if (input) {
            addTerm(
              groupIndex,
              bucket,
              input.value
            );
          }

          return;
        }

        if (action === 'remove-term') {
          removeTerm(
            parseInt(
              button.getAttribute('data-group'),
              10
            ),
            button.getAttribute('data-bucket'),
            parseInt(
              button.getAttribute('data-index'),
              10
            )
          );

          return;
        }

        if (action === 'add-group') {
          if (
            queryState.groups.length >= maxGroups
          ) {
            return;
          }

          queryState.groups.push({
            groupNo:
              queryState.groups.length + 1,
            include: [],
            and: [],
            andNot: []
          });

          renderCurrentStep();

          return;
        }

        if (action === 'remove-group') {
          var index =
            parseInt(
              button.getAttribute('data-group'),
              10
            );

          if (queryState.groups.length <= 1) {
            return;
          }

          queryState.groups.splice(
            index,
            1
          );

          renumberGroups();
          renderCurrentStep();

          return;
        }

        if (action === 'go-preview') {
          clearMessage();

          var error = validateBuild();

          if (error) {
            showMessage(
              error,
              'error'
            );

            return;
          }

          queryState.step = 2;
          renderCurrentStep();

          return;
        }

        if (action === 'back-build') {
          queryState.step = 1;
          renderCurrentStep();

          return;
        }

        if (action === 'go-save') {
          queryState.step = 3;
          renderCurrentStep();

          return;
        }

        if (action === 'back-preview') {
          queryState.step = 2;
          renderCurrentStep();

          return;
        }

        if (action === 'save-query') {
          var nameInput =
            document.getElementById('queryName');

          var statusInput =
            document.getElementById('queryStatus');

          queryState.name =
            normalizeText(
              nameInput
                ? nameInput.value
                : queryState.name
            );

          queryState.status =
            statusInput
              ? statusInput.value
              : queryState.status;

          if (!queryState.name) {
            showMessage(
              'Debes indicar un nombre para la consulta.',
              'error'
            );

            if (nameInput) {
              nameInput.focus();
            }

            return;
          }

          var payload =
            prepareQueryPayload();

          appsmith.updateModel(
            payload
          );

          showMessage(
            'Guardando consulta...',
            'info'
          );

          setSaveButtonState(
            true,
            'Guardando...'
          );

          setTimeout(function () {
            appsmith.triggerEvent(
              'onSaveQuery'
            );
          }, 150);

          return;
        }
      }
    );

    area.addEventListener(
      'keydown',
      function (event) {
        var input =
          event.target.closest(
            '[data-term-input="1"]'
          );

        if (!input) {
          return;
        }

        if (
          event.key !== 'Enter' &&
          event.key !== ','
        ) {
          return;
        }

        event.preventDefault();

        addTerm(
          parseInt(
            input.getAttribute('data-group'),
            10
          ),
          input.getAttribute('data-bucket'),
          input.value
        );
      }
    );

    area.addEventListener(
      'change',
      function (event) {
        if (event.target.id === 'useWeb') {
          queryState.useWeb =
            !!event.target.checked;

          var sourceCard =
            event.target.closest(
              '.source-card'
            );

          if (sourceCard) {
            sourceCard.classList.toggle(
              'selected',
              queryState.useWeb
            );
          }

          return;
        }

        var targetId =
          event.target.getAttribute(
            'data-target-id'
          );

        if (targetId) {
          queryState.selectedTargets[targetId] =
            !!event.target.checked;

          var targetCard =
            event.target.closest(
              '.target-choice'
            );

          if (targetCard) {
            targetCard.classList.toggle(
              'selected',
              !!event.target.checked
            );
          }

          return;
        }

        if (
          event.target.id === 'queryStatus'
        ) {
          queryState.status =
            event.target.value;
        }
      }
    );

    area.addEventListener(
      'input',
      function (event) {
        if (
          event.target.id === 'queryName'
        ) {
          queryState.name =
            event.target.value;
        }
      }
    );

    var lastTargets =
      (appsmith.model || {}).targetsJson || '';

    var lastSaveStatus =
      (appsmith.model || {}).querySaveStatus || '';

    function refreshFromModel() {
      var currentModel =
        appsmith.model || {};

      var currentTargets =
        currentModel.targetsJson || '';

      var currentSaveStatus =
        currentModel.querySaveStatus || '';

      if (
        currentTargets !== lastTargets
      ) {
        lastTargets = currentTargets;

        if (queryState.step === 1) {
          renderCurrentStep();
        }
      }

      if (
        currentSaveStatus &&
        currentSaveStatus !== lastSaveStatus
      ) {
        lastSaveStatus = currentSaveStatus;

        try {
          var saveResult =
            JSON.parse(currentSaveStatus);

          if (saveResult.status === 'success') {
            showMessage(
              'Consulta guardada correctamente.',
              'success'
            );

            setSaveButtonState(
              true,
              'Consulta guardada'
            );
          } else if (
            saveResult.status === 'error'
          ) {
            showMessage(
              saveResult.message ||
              'No fue posible guardar la consulta.',
              'error'
            );

            setSaveButtonState(
              false,
              'Guardar consulta'
            );
          }
        } catch (error) {
          showMessage(
            'No fue posible interpretar el resultado del guardado.',
            'error'
          );

          setSaveButtonState(
            false,
            'Guardar consulta'
          );
        }
      }
    }

    if (
      typeof appsmith.onModelChange ===
      'function'
    ) {
      appsmith.onModelChange(
        refreshFromModel
      );
    } else {
      setInterval(
        refreshFromModel,
        1500
      );
    }

    setTimeout(function () {
      appsmith.triggerEvent(
        'onLoadData'
      );
    }, 300);
  }

  try {
    var shellModel =
      appsmith.model || {};

    role =
      shellModel.userRole || 'viewer';

    var email =
      shellModel.userEmail || '';

    var active =
      shellModel.active || 'queries';

    document.getElementById(
      'userEmail'
    ).textContent = email;

    document.getElementById(
      'userRole'
    ).textContent =
      role.toUpperCase();

    document.getElementById(
      'userAvatar'
    ).textContent =
      email.charAt(0).toUpperCase() || 'A';

    var MENU = [
      {
        section: 'Análisis',
        items: [
          {
            id: 'dashboard',
            label: 'Dashboard',
            roles: [
              'admin',
              'analyst',
              'viewer'
            ]
          },
          {
            id: 'mentions',
            label: 'Menciones',
            roles: [
              'admin',
              'analyst',
              'viewer'
            ]
          },
          {
            id: 'analytics',
            label: 'Analítica',
            roles: [
              'admin',
              'analyst'
            ]
          },
          {
            id: 'competitors',
            label: 'Competencia',
            roles: [
              'admin',
              'analyst'
            ]
          }
        ]
      },
      {
        section: 'Gestión',
        items: [
          {
            id: 'targets',
            label: 'Objetivos',
            roles: [
              'admin',
              'analyst'
            ]
          },
          {
            id: 'alerts',
            label: 'Alertas',
            roles: [
              'admin',
              'analyst',
              'viewer'
            ]
          },
          {
            id: 'reports',
            label: 'Reportes',
            roles: [
              'admin',
              'analyst',
              'viewer'
            ]
          }
        ]
      },
      {
        section: 'Administración',
        items: [
          {
            id: 'tasks',
            label: 'Tareas de Scrapeo',
            roles: ['admin']
          },
          {
            id: 'integrations',
            label: 'Integraciones',
            roles: ['admin']
          },
          {
            id: 'users',
            label: 'Usuarios',
            roles: ['admin']
          },
          {
            id: 'roles',
            label: 'Roles y Permisos',
            roles: ['admin']
          },
          {
            id: 'audit',
            label: 'Auditoría',
            roles: ['admin']
          },
          {
            id: 'settings',
            label: 'Configuración',
            roles: ['admin']
          },
          {
            id: 'billing',
            label: 'Plan y Suscripción',
            roles: ['admin']
          }
        ]
      }
    ];

    var TITLES = {
      dashboard: 'Dashboard Ejecutivo',
      mentions: 'Menciones',
      analytics: 'Analítica',
      competitors: 'Competencia',
      targets: 'Objetivos Monitoreados',
      alerts: 'Alertas',
      reports: 'Reportes',
      tasks: 'Tareas de Scrapeo',
      integrations: 'Integraciones',
      users: 'Usuarios',
      roles: 'Roles y Permisos',
      audit: 'Auditoría',
      settings: 'Configuración',
      billing: 'Plan y Suscripción'
    };

    navMenu.innerHTML = '';

    MENU.forEach(function (section) {
      var visible = [];

      for (
        var i = 0;
        i < section.items.length;
        i++
      ) {
        if (
          section.items[i]
            .roles
            .indexOf(role) !== -1
        ) {
          visible.push(
            section.items[i]
          );
        }
      }

      if (visible.length === 0) {
        return;
      }

      var containsActive = false;

      for (
        var j = 0;
        j < visible.length;
        j++
      ) {
        if (
          visible[j].id === active
        ) {
          containsActive = true;
        }
      }

      var group =
        document.createElement('li');

      group.className =
        'nav-group' +
        (
          containsActive
            ? ''
            : ' collapsed'
        );

      var head =
        document.createElement('div');

      head.className =
        'nav-section-head';

      var headLabel =
        document.createElement('span');

      headLabel.textContent =
        section.section;

      head.appendChild(
        headLabel
      );

      head.addEventListener(
        'click',
        function () {
          group.classList.toggle(
            'collapsed'
          );
        }
      );

      group.appendChild(head);

      var list =
        document.createElement('ul');

      list.className =
        'nav-group-items';

      visible.forEach(function (item) {
        var li =
          document.createElement('li');

        li.className =
          'nav-item' +
          (
            item.id === active
              ? ' active'
              : ''
          );

        li.textContent =
          item.label;

        li.addEventListener(
          'click',
          function () {
            appsmith.triggerEvent(
              'go_' + item.id
            );
          }
        );

        list.appendChild(li);
      });

      group.appendChild(list);
      navMenu.appendChild(group);
    });

    document.getElementById(
      'viewTitle'
    ).textContent =
      TITLES[active] ||
      'Consultas';

    document.getElementById(
      'logoutBtn'
    ).addEventListener(
      'click',
      function () {
        appsmith.triggerEvent(
          'onLogout'
        );
      }
    );
  } catch (shellError) {
    navMenu.innerHTML =
      '<li style="' +
        'color:#A7CDDE;' +
        'padding:12px;' +
        'font-size:11px;' +
      '">' +
        'ERROR SHELL: ' +
        esc(shellError.message) +
      '</li>';

    return;
  }

  try {
    initQueriesModule();
  } catch (moduleError) {
    var area =
      document.getElementById(
        'contentArea'
      );

    if (area) {
      area.innerHTML =
        '<div style="' +
          'color:#2F323B;' +
          'background:rgba(167,205,222,0.18);' +
          'border:1px solid rgba(167,205,222,0.65);' +
          'border-radius:10px;' +
          'padding:14px;' +
          'font-size:12px;' +
        '">' +
          'ERROR MÓDULO CONSULTAS: ' +
          esc(moduleError.message) +
        '</div>';
    }
  }
});
